"use strict";

// Migration surface of the MarkItDown pin bump: an installation generated by
// the previous release keeps `markitdown-mcp@0.0.1a4` in its own config, and
// the compatibility story of this change is what a reinstall does with it.
// The canonical source (`.mcp.json`) ships `markitdown-mcp@0.0.1a7`.

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const { main: installOpenCode } = require("../../scripts/configure/install-global-opencode.js");
const { main: installCursor } = require("../../scripts/configure/install-cursor.js");
const { main: installCodex } = require("../../scripts/configure/install-codex.js");

function makeTempDir(t, prefix) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}

test("OpenCode global reinstall converges the MarkItDown pin to a7 and preserves user MCP entries", (t) => {
  const sandbox = makeTempDir(t, "mcp-pin-opencode-");
  const globalDir = path.join(sandbox, "opencode-home");
  const sourceDir = path.join(sandbox, "source");
  const outDir = path.join(sourceDir, "dist", "opencode");
  fs.mkdirSync(globalDir, { recursive: true });
  fs.mkdirSync(outDir, { recursive: true });

  // Generated by the previous release: the old pin plus a user-owned server.
  fs.writeFileSync(
    path.join(globalDir, "opencode.json"),
    JSON.stringify({
      mcp: {
        markitdown: { type: "local", command: ["uvx", "markitdown-mcp@0.0.1a4"], enabled: true },
        "user-owned": { type: "local", command: ["node", "user-server.js"], enabled: true },
      },
    }),
  );

  // The current canonical source ships the new pin.
  fs.writeFileSync(path.join(sourceDir, "package.json"), JSON.stringify({ name: "ospec-workflow", version: "9.9.9" }));
  fs.writeFileSync(
    path.join(outDir, "opencode.json"),
    JSON.stringify({
      mcp: { markitdown: { type: "local", command: ["uvx", "markitdown-mcp@0.0.1a7"], enabled: true } },
    }),
  );

  const code = installOpenCode(["--source", sourceDir, "--dest", globalDir, "--no-validate"], {
    fs,
    copyBinaryToTree: () => {},
    runConfigure: () => ({ exitCode: 0 }),
    spawnSync: () => ({ status: 0 }),
    stdout: { write: () => {} },
    stderr: { write: () => {} },
  });
  assert.equal(code, 0);

  const merged = JSON.parse(fs.readFileSync(path.join(globalDir, "opencode.json"), "utf8"));
  assert.deepEqual(merged.mcp.markitdown.command, ["uvx", "markitdown-mcp@0.0.1a7"]);
  assert.ok(merged.mcp["user-owned"], "the user-owned MCP server is preserved");
});

test("Cursor reinstall converges the MarkItDown pin to a7 and preserves user MCP entries", (t) => {
  const sandbox = makeTempDir(t, "mcp-pin-cursor-");
  const home = path.join(sandbox, "home");
  const sourceDir = path.join(sandbox, "source");
  const outDir = path.join(sourceDir, "dist", "cursor");
  fs.mkdirSync(path.join(home, ".cursor"), { recursive: true });
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, "hooks.json"), JSON.stringify({ version: 1, hooks: {} }));

  // Installed by the previous release: the old pin plus a user-owned server.
  fs.writeFileSync(
    path.join(home, ".cursor", "mcp.json"),
    JSON.stringify({
      mcpServers: {
        markitdown: { command: "uvx", args: ["markitdown-mcp@0.0.1a4"] },
        "user-owned": { command: "node", args: ["user-server.js"] },
      },
    }),
  );

  // The current canonical source ships the new pin.
  fs.writeFileSync(
    path.join(sourceDir, ".mcp.json"),
    JSON.stringify({ mcpServers: { markitdown: { command: "uvx", args: ["markitdown-mcp@0.0.1a7"] } } }),
  );

  const code = installCursor(["--source", sourceDir], {
    homedir: () => home,
    runConfigure: () => ({ files: [], summary: [], exitCode: 0, validation: null }),
    copyBinaryToTree: () => {},
    syncTreeByContent: () => ({ updated: [], unchanged: [] }),
    installHooksJson: () => {},
    validateInstalled: () => ({ errors: [], warnings: [] }),
    spawnSync: () => ({ status: 0 }),
    stdout: { write: () => {} },
    stderr: { write: () => {} },
  });
  assert.equal(code, 0);

  const merged = JSON.parse(fs.readFileSync(path.join(home, ".cursor", "mcp.json"), "utf8"));
  assert.deepEqual(merged.mcpServers.markitdown.args, ["markitdown-mcp@0.0.1a7"]);
  assert.ok(merged.mcpServers["user-owned"], "the user-owned MCP server is preserved");
});

test("Codex preserves a user-owned MarkItDown entry and lands a7 after the documented remove", (t) => {
  const sandbox = makeTempDir(t, "mcp-pin-codex-");
  const home = path.join(sandbox, "user-home");
  const sourceDir = path.join(sandbox, "source");
  const outDir = path.join(sourceDir, "dist", "codex");
  fs.mkdirSync(path.join(home, ".codex"), { recursive: true });
  fs.mkdirSync(path.join(home, ".agents", "skills"), { recursive: true });
  fs.mkdirSync(path.join(outDir, ".codex", "agents"), { recursive: true });
  fs.mkdirSync(path.join(outDir, "skills", "sdd-apply"), { recursive: true });
  fs.mkdirSync(path.join(outDir, "scripts"), { recursive: true });
  fs.writeFileSync(path.join(outDir, "AGENTS.md"), "# Codex Agents");
  fs.writeFileSync(path.join(outDir, ".codex", "agents", "sdd-apply.toml"), 'name = "sdd-apply"');
  fs.writeFileSync(path.join(outDir, "skills", "sdd-apply", "SKILL.md"), "# Skill");
  fs.writeFileSync(path.join(outDir, "hooks.json"), JSON.stringify({ hooks: {} }));
  fs.writeFileSync(
    path.join(sourceDir, ".mcp.json"),
    JSON.stringify({ mcpServers: { markitdown: { command: "uvx", args: ["markitdown-mcp@0.0.1a7"] } } }),
  );

  // Registered by the previous release: same name, old pin.
  const registered = [
    {
      name: "markitdown",
      transport: { type: "stdio", command: "uvx", args: ["markitdown-mcp@0.0.1a4"] },
    },
  ];

  const run = (deps = {}) =>
    installCodex(["--source", sourceDir, "--no-validate"], {
      fs,
      env: {},
      homedir: () => home,
      outDir,
      runConfigure: () => ({ exitCode: 0 }),
      findCodexBin: () => "codex",
      runCodexCommand(bin, args) {
        if (args.join(" ") === "mcp list --json") {
          return { status: 0, stdout: JSON.stringify(registered), stderr: "" };
        }
        if (args.slice(0, 3).join(" ") === "mcp add markitdown") {
          registered.push({
            name: "markitdown",
            transport: { type: "stdio", command: args[4], args: args.slice(5) },
          });
        }
        return { status: 0, stdout: "", stderr: "" };
      },
      spawnSync: () => ({ status: 0 }),
      stdout: { write: () => {} },
      stderr: { write: () => {} },
      ...deps,
    });

  // 1. A plain reinstall never clobbers a user-owned entry with another command.
  const stderr1 = [];
  assert.equal(run({ stderr: { write: (chunk) => stderr1.push(chunk) } }), 0);
  assert.match(stderr1.join(""), /already exists with a different command/);
  assert.deepEqual(registered.at(-1).transport.args, ["markitdown-mcp@0.0.1a4"]);

  // 2. The documented migration (`codex mcp remove markitdown`, then reinstall) lands the new pin.
  assert.equal(registered.shift().name, "markitdown");
  assert.equal(run(), 0);
  assert.deepEqual(registered.at(-1).transport.args, ["markitdown-mcp@0.0.1a7"]);
});
